<?= $this->extend('layout') ?><?= $this->section('content') ?><h1>Tenant Management</h1><div class="panel"><h2>Create tenant and first admin</h2><form method="post" action="<?= site_url('super-admin/tenants') ?>"><?= csrf_field() ?><div class="grid4"><div><label>Company name</label><input name="company_name" required></div><div><label>Company code</label><input name="company_code" pattern="[A-Za-z0-9]+" required></div><div><label>First admin name</label><input name="admin_name" required></div><div><label>First admin email</label><input type="email" name="admin_email" required></div><div><label>First admin password</label><input type="password" name="admin_password" minlength="8" required></div></div><p><button class="btn">Create tenant database</button></p></form></div><div class="panel" style="margin-top:16px"><h2>Tenants</h2><div class="table-wrap"><table><thead><tr><th>Company</th><th>Code</th><th>Database</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($tenants as $t): ?><tr><td><?= esc($t['company_name']) ?></td><td><?= esc($t['company_code']) ?></td><td><?= esc($t['db_name']) ?></td><td><?= esc($t['status']) ?></td><td><?= esc($t['created_at']) ?></td><td><form method="post" action="<?= site_url('super-admin/tenants/'.$t['id'].'/toggle') ?>" onsubmit="return confirm('Change tenant status?')"><?= csrf_field() ?><button class="btn gray">Activate / deactivate</button></form></td></tr><?php endforeach ?></tbody></table></div><form method="post" action="<?= site_url('super-admin/tenants/migrate-all') ?>"><?= csrf_field() ?><button class="btn" style="margin-top:12px">Apply schema update to all tenants</button></form></div><?= $this->endSection() ?>
